/// Brand-accurate social icons (§13): GitHub, LinkedIn, X, Reddit, Telegram.
/// Uses small inline SVGs to stay dependency-free and render correctly on all platforms.
library;

import 'package:flutter/material.dart';
import 'package:flutter_svg/flutter_svg.dart';

class SocialIcon extends StatelessWidget {
  final String platform;
  final double size;
  const SocialIcon({super.key, required this.platform, this.size = 20});

  @override
  Widget build(BuildContext context) {
    final svg = _svgs[platform.toLowerCase()];
    if (svg != null) {
      return SvgPicture.string(
        svg,
        width: size,
        height: size,
        colorFilter: ColorFilter.mode(Theme.of(context).iconTheme.color ?? Colors.black, BlendMode.srcIn),
      );
    }
    return Icon(Icons.link, size: size);
  }
}

